        i += 8;
        let body = u64::from_le_bytes(raw[i..i + 8].try_into().unwrap());
        i += 8;
        let nl = u16::from_le_bytes(raw[i..i + 2].try_into().unwrap()) as usize;
        i += 2;
        if i + nl > raw.len() {
            return Err(1);
