fn oct_u64(buf: &[u8]) -> Result<u64, i32> {
    let mut n = 0u64;
    let mut digit = false;
    for &b in buf {
        match b {
            0 | b' ' if !digit => continue,
            0 | b' ' => break,
            b'0'..=b'7' => {
                digit = true;
                n = n.checked_mul(8).and_then(|v| v.checked_add(u64::from(b-b'0'))).ok_or(1)?;
            }
            _ => return Err(1),
        }
    }
    if digit { Ok(n) } else { Err(1) }
}

pub fn scan(path: &str) -> Result<Vec<Row>, i32> {
    let raw = std::fs::read(path).map_err(|_| 1)?;
    if raw.len() < 1024 || raw.len() % 512 != 0 { return Err(1); }
    let mut rows = Vec::new();
    let mut off = 0usize;
    let mut ended = false;
    while off + 512 <= raw.len() {
        let blk = &raw[off..off+512];
        if blk.iter().all(|&b| b == 0) {
            ended = true;
            break;
        }
        if &blk[257..262] != b"ustar" { return Err(1); }
        let stored = oct_u64(&blk[148..156])?;
        let sum: u64 = blk.iter().enumerate().map(|(i,&b)| if (148..156).contains(&i) { 32 } else { u64::from(b) }).sum();
        if stored != sum { return Err(1); }
        let size = oct_u64(&blk[124..136])?;
        let nlen = blk[..100].iter().position(|&b| b == 0).unwrap_or(100);
        if nlen == 0 { return Err(1); }
        let name = std::str::from_utf8(&blk[..nlen]).map_err(|_| 1)?.to_string();
        let body = off.checked_add(512).ok_or(1)?;
        let padded = size.checked_add(511).ok_or(1)? / 512 * 512;
        let next = body.checked_add(usize::try_from(padded).map_err(|_| 1)?).ok_or(1)?;
        if next > raw.len() { return Err(1); }
        rows.push(Row { name, hdr: off as u64, size, body: body as u64, flag: blk[156] });
        off = next;
    }
    if rows.is_empty() || !ended { return Err(1); }
    Ok(rows)
}

pub fn load_body(path: &str, row: &Row) -> Result<Vec<u8>, i32> {
    let raw = std::fs::read(path).map_err(|_| 1)?;
    let s = usize::try_from(row.body).map_err(|_| 1)?;
    let n = usize::try_from(row.size).map_err(|_| 1)?;
    let e = s.checked_add(n).ok_or(1)?;
    if e > raw.len() { return Err(1); }
    Ok(raw[s..e].to_vec())
}
